import sys
from collections import defaultdict

class FileSystem:
    def __init__(self):
        self.dirs = {}  # maps dir_name -> {subdir_names, file_names}
        self.files = {}  # maps (dir_name, file_name) -> size
        self.parent = {}  # maps dir_name -> parent_dir_name

    def create_dir(self, parent_dir, new_dir):
        if new_dir not in self.dirs:
            self.dirs[new_dir] = {'subdirs': set(), 'files': set()}
            self.parent[new_dir] = parent_dir
            if parent_dir in self.dirs:
                self.dirs[parent_dir]['subdirs'].add(new_dir)

    def create_file(self, dir_name, file_name, file_size):
        if dir_name not in self.dirs:
            return
        self.dirs[dir_name]['files'].add(file_name)
        self.files[(dir_name, file_name)] = file_size

    def update_file(self, dir_name, file_name, new_size):
        if (dir_name, file_name) in self.files:
            self.files[(dir_name, file_name)] = new_size

    def delete_file(self, dir_name, file_name):
        if dir_name in self.dirs and file_name in self.dirs[dir_name]['files']:
            self.dirs[dir_name]['files'].discard(file_name)
            if (dir_name, file_name) in self.files:
                del self.files[(dir_name, file_name)]

    def query_dir(self, dir_name):
        if dir_name not in self.dirs:
            return []
        items = list(self.dirs[dir_name]['files']) + list(self.dirs[dir_name]['subdirs'])
        return sorted(items)

    def get_dir_size(self, dir_name):
        if dir_name not in self.dirs:
            return 0
        total = 0
        # Add files in this directory
        for file_name in self.dirs[dir_name]['files']:
            if (dir_name, file_name) in self.files:
                total += self.files[(dir_name, file_name)]
        # Add sizes from subdirectories
        for subdir in self.dirs[dir_name]['subdirs']:
            total += self.get_dir_size(subdir)
        return total

    def print_dir_contents(self, dir_name):
        items = self.query_dir(dir_name)
        for item in items:
            print(item)
        return items

    def print_dir_size(self, dir_name):
        size = self.get_dir_size(dir_name)
        print(f"Total size: {size}")
        return size

def main():
    fs = FileSystem()
    n = int(sys.stdin.readline().strip())

    for _ in range(n):
        parts = sys.stdin.readline().split()
        if not parts:
            continue
        op = int(parts[0])

        if op == 1:
            parent_dir = parts[1]
            new_dir = parts[2]
            if parent_dir not in fs.dirs:
                fs.dirs[parent_dir] = {'subdirs': set(), 'files': set()}
                fs.parent[parent_dir] = None
            fs.create_dir(parent_dir, new_dir)

        elif op == 2:
            dir_name = parts[1]
            file_name = parts[2]
            file_size = int(parts[3])
            if dir_name not in fs.dirs:
                fs.dirs[dir_name] = {'subdirs': set(), 'files': set()}
            fs.create_file(dir_name, file_name, file_size)

        elif op == 3:
            dir_name = parts[1]
            file_name = parts[2]
            new_size = int(parts[3])
            fs.update_file(dir_name, file_name, new_size)

        elif op == 4:
            dir_name = parts[1]
            file_name = parts[2]
            fs.delete_file(dir_name, file_name)

        elif op == 5:
            dir_name = parts[1]
            fs.print_dir_contents(dir_name)

        elif op == 6:
            dir_name = parts[1]
            fs.print_dir_size(dir_name)

if __name__ == "__main__":
    main()
